//! CRUD Gateway code generator.
//!
//! `generate_crud_gateway(&CrudGatewayDecl) -> String`
//!
//! Produces a complete `gen_storage.rs` file containing:
//! - `// 🤖 GENERATED BY FORGE` header
//! - Row type structs with `#[derive(sqlx::FromRow)]`
//! - `Storage` struct + `impl` block with `migrate()` + all CRUD methods
//! - Helper enum-mapping functions
//!
//! Standard ops use `sqlx::query!` / `sqlx::query_as!` for compile-time SQL validation.
//! Dynamic ops use `sqlx::QueryBuilder` for runtime assembly.

use crate::quarks::derive_attr::DeriveSet;
use crate::quarks::type_map::pg_rust_domain_type;
use crate::rust::atoms::pg_ddl::{MigrateTableInput, gen_migrate_table};
use crate::rust::atoms::sqlx_query::{
    BindParam, SqlxOpKind, SqlxQueryInput, WhereCondition, gen_sqlx_query,
};
use crate::rust::atoms::struct_def::{FieldDef, StructDefInput, Visibility, gen_struct_def};
use crate::rust::atoms::trait_contract::{TraitContractInput, TraitMethodDef, gen_trait_contract};
use nc_jarvis_ir::crud::*;

// ---------------------------------------------------------------------------
// Public entry point
// ---------------------------------------------------------------------------

/// Generate complete `gen_storage.rs` source from a CRUD gateway declaration.
pub fn generate_crud_gateway(decl: &CrudGatewayDecl) -> String {
    let mut out = String::with_capacity(16384);

    gen_header(&mut out);
    gen_imports(&mut out);
    out.push('\n');

    // Row type structs
    for table in &decl.tables {
        if let Some(rt) = &table.row_type {
            gen_row_type(&mut out, rt, table);
        }
    }

    // Storage struct via struct_def atom
    let storage_struct = StructDefInput {
        name: decl.gateway_struct.clone(),
        fields: vec![FieldDef {
            name: "pool".into(),
            rust_type: decl.pool_type.clone(),
            visibility: Visibility::Private,
            doc: None,
            serde_rename: None,
            serde_default: false,
            serde_skip_serializing_if: None,
            serde_default_fn: None,
            extra_field_attrs: vec![],
        }],
        derives: DeriveSet {
            debug: false,
            clone: false,
            serialize: false,
            deserialize: false,
            partial_eq: false,
            custom: vec![],
        },
        doc: None,
        serde_rename_all: None,
        extra_struct_attrs: vec![],
        default_impl: false,
    };
    out.push_str(&gen_struct_def(&storage_struct));
    out.push('\n');

    w(&mut out, 0, &format!("impl {} {{", decl.gateway_struct));
    w(
        &mut out,
        1,
        &format!("pub fn new(pool: {}) -> Self {{", decl.pool_type),
    );
    w(&mut out, 2, "Self { pool }");
    w(&mut out, 1, "}\n");

    gen_migrate(&mut out, decl);

    // Collect custom ops for trait generation; standard ops go in impl block
    let mut custom_ops: Vec<(&TableDecl, &CrudOpDecl)> = Vec::new();

    for table in &decl.tables {
        let has_standard = table.ops.iter().any(|op| op.kind != CrudOpKind::Custom);
        if has_standard {
            w(
                &mut out,
                1,
                &format!("// ========== {} ==========\n", table.name),
            );
        }
        for op in &table.ops {
            if op.kind == CrudOpKind::Custom {
                custom_ops.push((table, op));
            } else {
                gen_crud_op(&mut out, table, op);
                out.push('\n');
            }
        }
    }

    w(&mut out, 0, "}\n");

    // Helper functions
    for helper in &decl.helpers {
        gen_helper(&mut out, helper);
    }

    // ── Trait contract for custom ops (Generation Gap Pattern) ──
    if !custom_ops.is_empty() {
        gen_custom_trait(&mut out, &custom_ops);
    }

    out
}

// ---------------------------------------------------------------------------
// Header + imports
// ---------------------------------------------------------------------------

fn gen_header(out: &mut String) {
    out.push_str("// \u{1f916} GENERATED BY FORGE - DO NOT EDIT\n");
    out.push_str("// Source: intent.lisp (pattern crud-gateway)\n\n");
}

fn gen_imports(out: &mut String) {
    out.push_str("use crate::types::{Message, Session, SessionStatus};\n");
    out.push_str("use anyhow::Result;\n");
    out.push_str("use chrono::{DateTime, Utc};\n");
    out.push_str("use sqlx::PgPool;\n");
    out.push_str("use uuid::Uuid;\n");
}

// ---------------------------------------------------------------------------
// Row type structs
// ---------------------------------------------------------------------------

fn gen_row_type(out: &mut String, rt: &RowTypeDecl, table: &TableDecl) {
    // --- Struct definition via struct_def atom ---
    let custom_derives = if rt.derives.is_empty() {
        vec!["sqlx::FromRow".to_string(), "serde::Serialize".to_string()]
    } else {
        rt.derives.clone()
    };

    let fields: Vec<FieldDef> = table
        .columns
        .iter()
        .map(|col| FieldDef {
            name: col.name.clone(),
            rust_type: pg_rust_domain_type(&col.col_type, col.nullable),
            visibility: Visibility::Pub,
            doc: None,
            serde_rename: None,
            serde_default: false,
            serde_skip_serializing_if: None,
            serde_default_fn: None,
            extra_field_attrs: vec![],
        })
        .collect();

    let input = StructDefInput {
        name: rt.name.clone(),
        fields,
        derives: DeriveSet {
            debug: false,
            clone: false,
            serialize: false,
            deserialize: false,
            partial_eq: false,
            custom: custom_derives,
        },
        doc: None,
        serde_rename_all: None,
        extra_struct_attrs: vec![],
        default_impl: false,
    };

    out.push_str(&gen_struct_def(&input));
    out.push('\n');

    // --- Conversion impl (kept as-is — domain-specific logic) ---
    w(out, 0, &format!("impl {} {{", rt.name));
    w(
        out,
        1,
        &format!("fn {}(self) -> {} {{", rt.convert_fn, rt.target_type),
    );
    w(out, 2, &format!("{} {{", rt.target_type));
    for col in &table.columns {
        // Check if this field needs enum mapping
        if let Some(em) = rt.enum_maps.iter().find(|m| m.field == col.name) {
            w(
                out,
                3,
                &format!(
                    "{}: {}(&self.{}),",
                    col.name, em.converter, col.name
                ),
            );
        } else {
            w(out, 3, &format!("{}: self.{},", col.name, col.name));
        }
    }
    w(out, 2, "}");
    w(out, 1, "}");
    w(out, 0, "}\n");
}

// col_to_rust_type() removed — replaced by quarks::type_map::pg_rust_domain_type()

// ---------------------------------------------------------------------------
// migrate()
// ---------------------------------------------------------------------------

fn gen_migrate(out: &mut String, decl: &CrudGatewayDecl) {
    w(out, 1, "pub async fn migrate(&self) -> Result<()> {");

    for table in &decl.tables {
        let migrate_input = MigrateTableInput {
            table: table.name.clone(),
            columns: table.columns.clone(),
            composite_pk: table.composite_pk.clone(),
            unique_constraints: table.unique_constraints.clone(),
            indexes: table.indexes.clone(),
            pool_field: "self.pool".into(),
            indent: 2,
        };
        out.push_str(&gen_migrate_table(&migrate_input));
    }

    w(out, 2, "tracing::info!(\"Database migrations complete\");");
    w(out, 2, "Ok(())");
    w(out, 1, "}\n");
}

// ---------------------------------------------------------------------------
// CRUD op dispatch
// ---------------------------------------------------------------------------

fn gen_crud_op(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    match op.kind {
        CrudOpKind::Insert => gen_insert(out, table, op),
        CrudOpKind::InsertStruct => gen_insert_struct(out, table, op),
        CrudOpKind::SelectOne => gen_select_one(out, table, op),
        CrudOpKind::SelectMany => gen_select_many(out, table, op),
        CrudOpKind::SelectJson => gen_select_json(out, table, op),
        CrudOpKind::Update => gen_update(out, table, op),
        CrudOpKind::UpdateDynamic => gen_update_dynamic(out, table, op),
        CrudOpKind::UpdateCas => gen_update_cas(out, table, op),
        CrudOpKind::Delete => gen_delete(out, table, op),
        CrudOpKind::Upsert => gen_upsert(out, table, op),
        CrudOpKind::Count => gen_count(out, table, op),
        CrudOpKind::SyncBatch => gen_sync_batch(out, table, op),
        CrudOpKind::Custom => gen_custom(out, table, op),
    }
}

// ---------------------------------------------------------------------------
// Insert
// ---------------------------------------------------------------------------

fn gen_insert(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    // Auto-generated fields: let id = Uuid::new_v4(); etc.
    for auto in &op.auto_fields {
        if let Some(ref expr) = auto.via_expr {
            w(out, 2, &format!("let {} = {};", auto.name, expr));
        }
        if let Some(ref query) = auto.via_query {
            // Sub-query for auto field (e.g. next seq)
            w(
                out,
                2,
                &format!(
                    "let {name}: (i32,) = sqlx::query_as(\"{query}\")",
                    name = auto.name,
                    query = query
                ),
            );
            // Bind the first param (usually the grouping key)
            if !op.params.is_empty() {
                w(out, 3, &format!(".bind({})", op.params[0].name));
            }
            w(out, 3, ".fetch_one(&self.pool)");
            w(out, 3, ".await?;");
        }
    }

    // Build column + bind lists
    let mut columns = Vec::new();
    let mut binds = Vec::new();

    // Auto fields first
    for auto in &op.auto_fields {
        columns.push(auto.name.clone());
        if auto.via_query.is_some() {
            binds.push(BindParam { expr: format!("{}.0", auto.name) });
        } else {
            binds.push(BindParam { expr: auto.name.clone() });
        }
    }

    // Default fields
    for (col, val) in &op.defaults {
        columns.push(col.clone());
        binds.push(BindParam { expr: format!("\"{}\"", val) });
    }

    // Explicit params
    for param in &op.params {
        columns.push(param.name.clone());
        if let Some(ref cast) = param.cast_to {
            binds.push(BindParam { expr: format!("{} as {}", param.name, cast) });
        } else {
            binds.push(BindParam { expr: param.name.clone() });
        }
    }

    let input = SqlxQueryInput {
        table: table.name.clone(),
        op: SqlxOpKind::Insert,
        columns,
        binds,
        indent: 2,
        ..Default::default()
    };
    out.push_str(&gen_sqlx_query(&input));

    // Side effect
    if let Some(ref se) = op.side_effect {
        out.push('\n');
        let se_sql = se.replace("$task_id", "$1");
        w(out, 2, &format!("sqlx::query!(\"{se_sql}\", task_id)"));
        w(out, 2, ".execute(&self.pool)");
        w(out, 2, ".await?;");
    }

    // Return
    if op.returns == "()" {
        w(out, 2, "Ok(())");
    } else if op.returns == "Uuid" {
        w(out, 2, "Ok(id)");
    } else {
        // Construct return type from auto fields + defaults + None for nullable cols
        w(out, 2, &format!("Ok({} {{", op.returns));
        for col in &table.columns {
            let val = if let Some(auto) = op.auto_fields.iter().find(|a| a.name == col.name) {
                if auto.via_query.is_some() {
                    format!("{}.0 as i32", auto.name)
                } else {
                    auto.name.clone()
                }
            } else if let Some((_, default_val)) = op.defaults.iter().find(|(k, _)| k == &col.name) {
                // Map string defaults to enum variants if row-type has enum_map
                if let Some(rt) = &table.row_type {
                    if let Some(em) = rt.enum_maps.iter().find(|m| m.field == col.name) {
                        format!("{}::Idle /* default: {} */", em.target_type, default_val)
                    } else {
                        format!("\"{}\".to_string()", default_val)
                    }
                } else {
                    format!("\"{}\".to_string()", default_val)
                }
            } else if op.params.iter().any(|p| p.name == col.name) {
                col.name.clone()
            } else if col.nullable {
                "None".to_string()
            } else {
                format!("Default::default() /* TODO: {} */", col.name)
            };
            w(out, 3, &format!("{}: {},", col.name, val));
        }
        w(out, 2, "})");
    }

    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// InsertStruct
// ---------------------------------------------------------------------------

fn gen_insert_struct(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let columns: Vec<&str> = table.columns.iter().map(|c| c.name.as_str()).collect();
    let placeholders: Vec<String> = (1..=columns.len()).map(|i| format!("${i}")).collect();

    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({})",
        table.name,
        columns.join(", "),
        placeholders.join(", ")
    );

    // Determine the struct param name
    let param_name = if !op.params.is_empty() {
        &op.params[0].name
    } else {
        "msg"
    };

    w(out, 2, &format!("sqlx::query!(\"{sql}\","));
    for (i, col) in columns.iter().enumerate() {
        let comma = if i < columns.len() - 1 { "," } else { "" };
        w(out, 3, &format!("{param_name}.{col}{comma}"));
    }
    w(out, 2, ")");
    w(out, 2, ".execute(&self.pool)");
    w(out, 2, ".await?;");
    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SelectOne
// ---------------------------------------------------------------------------

fn gen_select_one(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let columns: Vec<String> = if op.select_cols.is_empty() {
        table.columns.iter().map(|c| c.name.clone()).collect()
    } else {
        op.select_cols.clone()
    };

    let (where_conditions, binds) = build_where_atoms(&op.where_clause);

    let row_type = table.row_type.as_ref().map(|rt| rt.name.clone());
    let input = SqlxQueryInput {
        table: table.name.clone(),
        op: SqlxOpKind::SelectOne,
        columns,
        binds,
        where_conditions,
        row_type: row_type.clone(),
        indent: 2,
        ..Default::default()
    };

    w(out, 2, &format!("let row = "));
    // Strip trailing newline from atom output so "let row = " prefix joins correctly
    let query_code = gen_sqlx_query(&input);
    // The atom output starts with indentation; we already wrote "let row = " at indent 2,
    // so we need to trim the leading whitespace from the first line of query_code
    let trimmed = query_code.trim_start();
    out.push_str(trimmed);

    if let Some(ref rt) = table.row_type {
        w(
            out,
            2,
            &format!("Ok(row.map(|r| r.{}()))", rt.convert_fn),
        );
    } else {
        w(out, 2, "Ok(row)");
    }
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SelectMany
// ---------------------------------------------------------------------------

fn gen_select_many(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let select_cols = if op.select_cols.is_empty() {
        table
            .columns
            .iter()
            .map(|c| c.name.as_str())
            .collect::<Vec<_>>()
            .join(", ")
    } else {
        op.select_cols.join(", ")
    };

    let (where_clause, mut binds) = build_where(&op.where_clause, 1);
    let mut next_idx = binds.len() as u32 + 1;

    let order = op
        .order
        .as_ref()
        .map(|o| format!(" ORDER BY {o}"))
        .unwrap_or_default();

    // Check for limit param
    let limit_clause = if op.params.iter().any(|p| p.name == "limit") {
        let s = format!(" LIMIT ${next_idx}");
        binds.push("limit".to_string());
        next_idx += 1;
        s
    } else {
        String::new()
    };

    // Check for offset param
    let offset_clause = if op.params.iter().any(|p| p.name == "offset") {
        let s = format!(" OFFSET ${next_idx}");
        binds.push("offset".to_string());
        s
    } else {
        String::new()
    };

    let sql = format!(
        "SELECT {select_cols} FROM {}{where_clause}{order}{limit_clause}{offset_clause}",
        table.name
    );

    let has_row_type = table.row_type.is_some();
    if has_row_type {
        let rt = table.row_type.as_ref().unwrap();
        w(
            out,
            2,
            &format!("let rows = sqlx::query_as!({}," , rt.name),
        );
    } else {
        w(out, 2, "let rows = sqlx::query!(");
    }
    w(out, 3, &format!("\"{sql}\","));
    for (i, b) in binds.iter().enumerate() {
        let comma = if i < binds.len() - 1 { "," } else { "" };
        w(out, 3, &format!("{b}{comma}"));
    }
    w(out, 2, ")");
    w(out, 2, ".fetch_all(&self.pool)");
    w(out, 2, ".await?;");

    if has_row_type {
        let rt = table.row_type.as_ref().unwrap();
        let map = format!("Ok(rows.into_iter().map(|r| r.{}()).collect())", rt.convert_fn);
        if op.post_process.as_deref() == Some("reverse") {
            w(out, 2, &format!(
                "let mut result: Vec<_> = rows.into_iter().map(|r| r.{}()).collect();",
                rt.convert_fn
            ));
            w(out, 2, "result.reverse();");
            w(out, 2, "Ok(result)");
        } else {
            w(out, 2, &map);
        }
    } else {
        // No row type — return raw rows with optional field casts
        // For select_cols with known return like Vec<(String, u64)>, generate map
        if op.returns.contains("u64") && op.select_cols.len() == 2 {
            w(
                out,
                2,
                "Ok(rows.into_iter().map(|r| (r.file_path, r.byte_offset as u64)).collect())",
            );
        } else {
            w(out, 2, "Ok(rows)");
        }
    }
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SelectJson
// ---------------------------------------------------------------------------

fn gen_select_json(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let (where_clause, mut binds) = build_where(&op.where_clause, 1);
    let mut next_idx = binds.len() as u32 + 1;

    // Fixed WHERE conditions
    let fixed_where = if !op.where_fixed.is_empty() {
        let conditions = op.where_fixed.join(" AND ");
        if where_clause.is_empty() {
            format!(" WHERE {conditions}")
        } else {
            format!(" AND {conditions}")
        }
    } else {
        String::new()
    };

    let order = op
        .order
        .as_ref()
        .map(|o| format!(" ORDER BY {o}"))
        .unwrap_or_default();

    let limit_clause = if op.params.iter().any(|p| p.name == "limit") {
        let s = format!(" LIMIT ${next_idx}");
        binds.push("limit".to_string());
        next_idx += 1;
        let _ = next_idx;
        s
    } else {
        String::new()
    };

    let sql = format!(
        "SELECT to_jsonb(t) AS val FROM {} t{where_clause}{fixed_where}{order}{limit_clause}",
        table.name
    );

    let is_option = op.returns.starts_with("Option<");
    let fetch = if is_option {
        "fetch_optional"
    } else {
        "fetch_all"
    };

    w(
        out,
        2,
        &format!("let rows: Vec<(serde_json::Value,)> = sqlx::query_as("),
    );
    w(out, 3, &format!("\"{sql}\""));
    w(out, 2, ")");
    for b in &binds {
        w(out, 2, &format!(".bind({b})"));
    }
    w(out, 2, &format!(".{fetch}(&self.pool)"));
    w(out, 2, ".await?;");

    if is_option {
        w(out, 2, "Ok(rows.map(|r| r.0))");
    } else {
        w(out, 2, "Ok(rows.into_iter().map(|r| r.0).collect())");
    }
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Update
// ---------------------------------------------------------------------------

fn gen_update(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let mut set_parts = Vec::new();
    let mut binds = Vec::new();
    let mut idx = 1u32;

    for sf in &op.set_fields {
        if let Some(ref lit) = sf.literal {
            set_parts.push(format!("{} = {}", sf.column, lit));
        } else if let Some(ref via) = sf.via_fn {
            set_parts.push(format!("{} = {}", sf.column, via));
        } else {
            set_parts.push(format!("{} = ${idx}", sf.column));
            if let Some(ref conv) = sf.converter {
                binds.push(format!("{}({})", conv, sf.param_name.as_deref().unwrap_or(&sf.column)));
            } else {
                binds.push(sf.param_name.clone().unwrap_or_else(|| sf.column.clone()));
            }
            idx += 1;
        }
    }

    // WHERE clause
    for wp in &op.where_clause {
        binds.push(wp.bind_name.clone().unwrap_or_else(|| wp.name.clone()));
        idx += 1;
    }

    let where_parts: Vec<String> = op
        .where_clause
        .iter()
        .enumerate()
        .map(|(i, wp)| {
            let param_idx = binds.len() - op.where_clause.len() + i + 1;
            format!("{} = ${param_idx}", wp.name)
        })
        .collect();

    let where_clause = if where_parts.is_empty() {
        String::new()
    } else {
        format!(" WHERE {}", where_parts.join(" AND "))
    };

    let sql = format!(
        "UPDATE {} SET {}{where_clause}",
        table.name,
        set_parts.join(", ")
    );

    w(out, 2, &format!("sqlx::query!(\"{sql}\","));
    for (i, b) in binds.iter().enumerate() {
        let comma = if i < binds.len() - 1 { "," } else { "" };
        w(out, 3, &format!("{b}{comma}"));
    }
    w(out, 2, ")");
    w(out, 2, ".execute(&self.pool)");
    w(out, 2, ".await?;");
    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// UpdateDynamic — uses QueryBuilder
// ---------------------------------------------------------------------------

fn gen_update_dynamic(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    w(out, 2, "let mut sets = Vec::new();");
    w(out, 2, "let mut idx = 2u32; // $1 is id");

    for field in &op.dynamic_fields {
        w(
            out,
            2,
            &format!(
                "if updates.get(\"{field}\").is_some() {{ sets.push(format!(\"{field} = ${{}}\", idx)); idx += 1; }}"
            ),
        );
    }

    w(out, 2, "let _ = idx;");
    w(out, 2, "if sets.is_empty() { return Ok(()); }");

    // Auto-set fields (e.g., updated_at = now())
    for (col, via) in &op.auto_set {
        w(
            out,
            2,
            &format!("sets.push(\"{col} = {via}\".to_string());"),
        );
    }

    w(
        out,
        2,
        &format!(
            "let sql = format!(\"UPDATE {} SET {{}} WHERE id = $1\", sets.join(\", \"));",
            table.name
        ),
    );
    w(out, 2, "let mut q = sqlx::query(&sql).bind(id);");

    for field in &op.dynamic_fields {
        w(
            out,
            2,
            &format!(
                "if let Some(v) = updates[\"{field}\"].as_str() {{ q = q.bind(v.to_string()); }}"
            ),
        );
    }

    w(out, 2, "q.execute(&self.pool).await?;");
    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// UpdateCas — compare-and-swap with preconditions
// ---------------------------------------------------------------------------

fn gen_update_cas(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let mut set_parts = Vec::new();
    let mut binds = Vec::new();
    let mut idx = 1u32;

    // WHERE pk
    for wp in &op.where_clause {
        binds.push(wp.name.clone());
        idx += 1;
    }

    // SET fields
    for sf in &op.set_fields {
        if let Some(ref lit) = sf.literal {
            set_parts.push(format!("{} = {}", sf.column, lit));
        } else if let Some(ref via) = sf.via_fn {
            set_parts.push(format!("{} = {}", sf.column, via));
        } else if let Some(ref pn) = sf.param_name {
            set_parts.push(format!("{} = ${idx}", sf.column));
            binds.push(pn.clone());
            idx += 1;
        }
    }

    let _ = idx;

    let where_pk: Vec<String> = op
        .where_clause
        .iter()
        .enumerate()
        .map(|(i, wp)| format!("{} = ${}", wp.name, i + 1))
        .collect();

    let mut all_conditions = where_pk;
    all_conditions.extend(op.preconditions.iter().cloned());

    let sql = format!(
        "UPDATE {} SET {} WHERE {}",
        table.name,
        set_parts.join(", "),
        all_conditions.join(" AND ")
    );

    w(out, 2, &format!("let result = sqlx::query!(\"{sql}\","));
    for (i, b) in binds.iter().enumerate() {
        let comma = if i < binds.len() - 1 { "," } else { "" };
        w(out, 3, &format!("{b}{comma}"));
    }
    w(out, 2, ")");
    w(out, 2, ".execute(&self.pool)");
    w(out, 2, ".await?;");
    w(out, 2, "Ok(result.rows_affected() > 0)");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Delete
// ---------------------------------------------------------------------------

fn gen_delete(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let (where_clause, binds) = build_where(&op.where_clause, 1);
    let sql = format!("DELETE FROM {}{where_clause}", table.name);

    let result_binding = if op.returns == "bool" {
        "let result = "
    } else {
        ""
    };

    w(out, 2, &format!("{result_binding}sqlx::query!(\"{sql}\","));
    for (i, b) in binds.iter().enumerate() {
        let comma = if i < binds.len() - 1 { "," } else { "" };
        w(out, 3, &format!("{b}{comma}"));
    }
    w(out, 2, ")");
    w(out, 2, ".execute(&self.pool)");
    w(out, 2, ".await?;");

    if op.returns == "bool" {
        w(out, 2, "Ok(result.rows_affected() > 0)");
    } else {
        w(out, 2, "Ok(())");
    }
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Upsert
// ---------------------------------------------------------------------------

fn gen_upsert(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let mut columns = Vec::new();
    let mut placeholders = Vec::new();
    let mut binds = Vec::new();
    let mut idx = 1u32;

    // Map params to table columns by position; use column names for SQL,
    // param names/casts for bind values
    for (i, param) in op.params.iter().enumerate() {
        // Use the table column name if available, otherwise param name
        let col_name = table
            .columns
            .get(i)
            .map(|c| c.name.as_str())
            .unwrap_or(&param.name);
        columns.push(col_name.to_string());
        placeholders.push(format!("${idx}"));
        if let Some(ref cast) = param.cast_to {
            binds.push(format!("{} as {}", param.name, cast));
        } else {
            binds.push(param.name.clone());
        }
        idx += 1;
    }

    let conflict = op
        .on_conflict
        .as_deref()
        .unwrap_or("(id) DO NOTHING");

    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({}) ON CONFLICT {conflict}",
        table.name,
        columns.join(", "),
        placeholders.join(", ")
    );

    w(out, 2, &format!("sqlx::query!(\"{sql}\","));
    for (i, b) in binds.iter().enumerate() {
        let comma = if i < binds.len() - 1 { "," } else { "" };
        w(out, 3, &format!("{b}{comma}"));
    }
    w(out, 2, ")");
    w(out, 2, ".execute(&self.pool)");
    w(out, 2, ".await?;");

    if op.returns == "()" {
        w(out, 2, "Ok(())");
    } else {
        w(out, 2, "Ok(/* construct return */)");
    }
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Count
// ---------------------------------------------------------------------------

fn gen_count(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let (where_clause, binds) = build_where(&op.where_clause, 1);
    let sql = format!("SELECT COUNT(*) FROM {}{where_clause}", table.name);

    w(out, 2, &format!("let row: (i64,) = sqlx::query_as(\"{sql}\")"));
    for b in &binds {
        w(out, 3, &format!(".bind({b})"));
    }
    w(out, 2, ".fetch_one(&self.pool)");
    w(out, 2, ".await?;");
    w(out, 2, "Ok(row.0)");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SyncBatch
// ---------------------------------------------------------------------------

fn gen_sync_batch(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    if let Some(ref dw) = op.delete_where {
        w(
            out,
            2,
            &format!(
                "sqlx::query!(\"DELETE FROM {} WHERE {dw}\", {})",
                table.name,
                op.params.first().map(|p| p.name.as_str()).unwrap_or("id")
            ),
        );
        w(out, 2, ".execute(&self.pool)");
        w(out, 2, ".await?;\n");
    }

    if let Some(ref each_var) = op.insert_each {
        let param_name = op
            .params
            .get(1)
            .map(|p| p.name.as_str())
            .unwrap_or("items");
        w(
            out,
            2,
            &format!("for {each_var} in {param_name} {{"),
        );
        w(out, 3, "// TODO: insert each row");
        w(out, 2, "}");
    }

    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Custom — skeleton with SQL comment
// ---------------------------------------------------------------------------

fn gen_custom(out: &mut String, _table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    if let Some(ref sql) = op.custom_sql {
        w(out, 2, &format!("// SQL: {sql}"));
        w(out, 2, "todo!(\"custom op — hand-write or extend codegen\")");
    } else if !op.custom_queries.is_empty() {
        for (name, sql) in &op.custom_queries {
            w(out, 2, &format!("// {name}: {sql}"));
        }
        w(out, 2, "todo!(\"aggregate custom op\")");
    } else {
        w(out, 2, "todo!(\"custom op\")");
    }

    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Helper functions
// ---------------------------------------------------------------------------

fn gen_helper(out: &mut String, helper: &HelperFnDecl) {
    let param_type = &helper.param_type;
    let return_type = &helper.return_type;

    w(
        out,
        0,
        &format!(
            "fn {}({}: {param_type}) -> {return_type} {{",
            helper.name,
            if return_type.contains("&'static") {
                "status"
            } else {
                "s"
            },
        ),
    );

    if return_type.contains("&'static") {
        // Enum -> str mapping
        w(out, 1, "match status {");
        for (from, to) in &helper.mappings {
            w(
                out,
                2,
                &format!("{param_type}::{from} => \"{to}\","),
            );
        }
        w(out, 1, "}");
    } else {
        // str -> Enum mapping
        w(out, 1, "match s {");
        for (from, to) in &helper.mappings {
            w(
                out,
                2,
                &format!("\"{from}\" => {return_type}::{to},"),
            );
        }
        if let Some(ref d) = helper.default {
            w(out, 2, &format!("_ => {return_type}::{d},"));
        }
        w(out, 1, "}");
    }

    w(out, 0, "}\n");
}

// ---------------------------------------------------------------------------
// Custom ops → Trait contract (Generation Gap Pattern)
// ---------------------------------------------------------------------------

fn gen_custom_trait(out: &mut String, ops: &[(&TableDecl, &CrudOpDecl)]) {
    // Banner comments (kept as-is — not part of trait_contract atom)
    w(out, 0, "// ═══════════════════════════════════════════════════════════");
    w(out, 0, "// 🤖 GENERATED CONTRACT — implement in storage_custom.rs");
    w(out, 0, "// These signatures are locked by intent.lisp declarations.");
    w(out, 0, "// Rust compiler enforces your impl matches these exactly.");
    w(out, 0, "// ═══════════════════════════════════════════════════════════\n");

    // Build trait methods from custom ops
    let methods: Vec<TraitMethodDef> = ops
        .iter()
        .map(|(table, op)| {
            // Collect doc lines
            let mut doc_parts = Vec::new();
            if let Some(ref sql) = op.custom_sql {
                doc_parts.push(format!("SQL: {sql}"));
            }
            for (name, sql) in &op.custom_queries {
                doc_parts.push(format!("{name}: {sql}"));
            }
            if let Some(ref logic) = op.logic {
                doc_parts.push(format!("Logic: {logic}"));
            }
            doc_parts.push(format!("Table: {}", table.name));

            // Collect params (where clause + explicit params)
            let mut params: Vec<(String, String)> = Vec::new();
            for wp in &op.where_clause {
                let name = wp.bind_name.as_deref().unwrap_or(&wp.name);
                params.push((name.to_string(), rust_param_type(&wp.rust_type).to_string()));
            }
            for p in &op.params {
                params.push((p.name.clone(), rust_param_type(&p.rust_type).to_string()));
            }

            TraitMethodDef {
                name: op.name.clone(),
                params,
                return_type: format!("Result<{}>", op.returns),
                is_async: true,
                doc: Some(doc_parts.join(" | ")),
                has_default: false,
                has_self: true,
            }
        })
        .collect();

    let trait_input = TraitContractInput {
        name: "StorageCustomLogic".into(),
        doc: None,
        methods,
        is_async_trait: false,
    };

    out.push_str(&gen_trait_contract(&trait_input));
    out.push('\n');
}

// ---------------------------------------------------------------------------
// Shared utilities
// ---------------------------------------------------------------------------

/// Map column-vocabulary types to Rust types for fn signatures.
fn rust_param_type(s: &str) -> &str {
    match s {
        "uuid" => "Uuid",
        "text" => "&str",
        "integer" | "int" => "i32",
        "bigint" => "i64",
        "boolean" | "bool" => "bool",
        "float8" => "f64",
        "jsonb" => "serde_json::Value",
        "timestamptz" => "DateTime<Utc>",
        other => other, // pass through already-correct Rust types
    }
}

fn build_fn_sig(op: &CrudOpDecl) -> String {
    let mut params_str = String::from("&self");

    // Collect all params (where + explicit params)
    for wp in &op.where_clause {
        let name = wp.bind_name.as_deref().unwrap_or(&wp.name);
        params_str.push_str(&format!(", {}: {}", name, rust_param_type(&wp.rust_type)));
    }
    for p in &op.params {
        params_str.push_str(&format!(", {}: {}", p.name, rust_param_type(&p.rust_type)));
    }
    // For update-dynamic, add the updates param
    if op.kind == CrudOpKind::UpdateDynamic {
        params_str.push_str(", updates: &serde_json::Value");
    }
    // For update-cas, add set field params
    if op.kind == CrudOpKind::UpdateCas {
        for sf in &op.set_fields {
            if let Some(ref pn) = sf.param_name {
                if let Some(ref rt) = sf.rust_type {
                    params_str.push_str(&format!(", {pn}: {rt}"));
                }
            }
        }
    }

    format!(
        "pub async fn {}({params_str}) -> Result<{}> {{",
        op.name, op.returns
    )
}

/// Convert IR where-clause params to atom-level WhereCondition + BindParam.
fn build_where_atoms(params: &[ParamDecl]) -> (Vec<WhereCondition>, Vec<BindParam>) {
    let mut conditions = Vec::new();
    let mut binds = Vec::new();
    for p in params {
        conditions.push(WhereCondition {
            column: p.name.clone(),
            op: p.op.clone(),
        });
        binds.push(BindParam {
            expr: p.bind_name.clone().unwrap_or_else(|| p.name.clone()),
        });
    }
    (conditions, binds)
}

fn build_where(params: &[ParamDecl], start_idx: u32) -> (String, Vec<String>) {
    if params.is_empty() {
        return (String::new(), vec![]);
    }
    let mut parts = Vec::new();
    let mut binds = Vec::new();
    for (i, p) in params.iter().enumerate() {
        let idx = start_idx + i as u32;
        parts.push(format!("{} = ${idx}", p.name));
        binds.push(p.bind_name.clone().unwrap_or_else(|| p.name.clone()));
    }
    (format!(" WHERE {}", parts.join(" AND ")), binds)
}

/// Write a line with indentation.
fn w(out: &mut String, indent: usize, line: &str) {
    for _ in 0..indent {
        out.push_str("    ");
    }
    out.push_str(line);
    out.push('\n');
}

